<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0">
<title>Il Nostro Matrimonio – 26 Luglio 2026</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,600;1,300;1,400&family=Montserrat:wght@300;400;500;600&display=swap" rel="stylesheet">
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --aqua-deep:    #0a4f5c;
    --aqua-mid:     #1a7a8a;
    --aqua-light:   #5bbfcc;
    --aqua-pale:    #a8dde6;
    --aqua-foam:    #d6f0f4;
    --aqua-mist:    #eef8fa;
    --gold:         #c8a84b;
    --gold-light:   #e8cc80;
    --gold-pale:    #f5e9c4;
    --white:        #ffffff;
    --text-dark:    #0d3540;
    --text-mid:     #1a5f70;
    --font-display: 'Cormorant Garamond', Georgia, serif;
    --font-body:    'Montserrat', 'Helvetica Neue', sans-serif;
  }

  html, body {
    width: 100%;
    min-height: 100%;
    background: var(--aqua-deep);
    -webkit-font-smoothing: antialiased;
  }

  .page {
    max-width: 480px;
    margin: 0 auto;
    background: var(--white);
    position: relative;
    overflow: hidden;
  }

  /* ─── HERO IMAGE (prima immagine allegata) ─── */
  .hero-img-wrap {
    position: relative;
    width: 100%;
    overflow: hidden;
  }
  .hero-img-wrap img {
    width: 100%;
    display: block;
    object-fit: cover;
  }
  .hero-img-overlay {
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 60px;
    background: linear-gradient(to bottom, transparent, var(--white));
  }

  /* ─── DATE IMAGE (seconda immagine allegata) ─── */
  .date-img-wrap {
    position: relative;
    width: 100%;
    overflow: hidden;
    margin-top: -2px;
  }
  .date-img-wrap img {
    width: 100%;
    display: block;
    object-fit: cover;
  }
  .date-img-overlay-top {
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 50px;
    background: linear-gradient(to bottom, var(--white), transparent);
  }
  .date-img-overlay-bottom {
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 60px;
    background: linear-gradient(to bottom, transparent, var(--aqua-mist));
  }

  /* ─── GOLD LINE ─── */
  .gold-line {
    width: 60px;
    height: 2px;
    background: linear-gradient(90deg, transparent, var(--gold), transparent);
    margin: 0 auto 20px;
    border-radius: 2px;
  }

  /* ─── SECTION BASE ─── */
  .section {
    padding: 36px 28px;
    position: relative;
  }
  .section-alt { background: var(--aqua-mist); }
  .section-dark {
    background: linear-gradient(135deg, var(--aqua-deep) 0%, var(--aqua-mid) 100%);
    color: var(--white);
  }

  .section-icon {
    width: 46px; height: 46px;
    border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    margin: 0 auto 14px;
    font-size: 22px;
  }
  .icon-aqua { background: linear-gradient(135deg, var(--aqua-pale), var(--aqua-foam)); }
  .icon-gold { background: linear-gradient(135deg, var(--gold-pale), #fff); }
  .icon-dark { background: rgba(255,255,255,0.12); }
  .icon-green { background: linear-gradient(135deg, #d4f5e2, #f0fdf4); }

  .section-title {
    font-family: var(--font-display);
    font-size: clamp(1.5rem, 7vw, 2rem);
    font-weight: 600;
    color: var(--aqua-deep);
    text-align: center;
    margin-bottom: 6px;
  }
  .section-title-light { color: var(--white) !important; }
  .section-subtitle {
    font-family: var(--font-body);
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--aqua-light);
    text-align: center;
    margin-bottom: 20px;
  }
  .section-subtitle-light { color: rgba(255,255,255,0.55) !important; }

  /* ─── INFO CARD ─── */
  .info-card {
    background: var(--white);
    border-radius: 16px;
    padding: 20px 18px;
    margin-bottom: 12px;
    box-shadow: 0 2px 14px rgba(10,79,92,0.08);
    display: flex;
    align-items: flex-start;
    gap: 14px;
  }
  .info-card-icon { font-size: 24px; flex-shrink: 0; margin-top: 2px; }
  .info-card-label {
    font-family: var(--font-body);
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--aqua-light);
    margin-bottom: 4px;
  }
  .info-card-value {
    font-family: var(--font-display);
    font-size: clamp(1.1rem, 5vw, 1.4rem);
    font-weight: 600;
    color: var(--aqua-deep);
    line-height: 1.2;
  }
  .info-card-detail {
    font-family: var(--font-body);
    font-size: 12px;
    color: #5a8a96;
    margin-top: 4px;
    line-height: 1.5;
  }

  /* ─── HIGHLIGHT BOX ─── */
  .highlight-box {
    background: linear-gradient(135deg, var(--aqua-foam) 0%, var(--gold-pale) 100%);
    border-radius: 16px;
    padding: 22px 20px;
    border-left: 4px solid var(--gold);
    margin: 12px 0;
  }
  .highlight-box-icon { font-size: 28px; margin-bottom: 8px; }
  .highlight-box-title {
    font-family: var(--font-display);
    font-size: clamp(1rem, 4.5vw, 1.2rem);
    font-weight: 600;
    color: var(--aqua-deep);
    margin-bottom: 8px;
  }
  .highlight-box-text {
    font-family: var(--font-body);
    font-size: 13px;
    color: var(--text-dark);
    line-height: 1.65;
  }
  .highlight-box-text strong { color: var(--aqua-mid); font-weight: 600; }

  /* ─── DARK CARD ─── */
  .dark-card {
    background: rgba(255,255,255,0.1);
    border-radius: 16px;
    padding: 20px 18px;
    margin-bottom: 12px;
    border: 1px solid rgba(255,255,255,0.15);
    display: flex;
    align-items: flex-start;
    gap: 14px;
  }
  .dark-card-icon { font-size: 24px; flex-shrink: 0; margin-top: 2px; }
  .dark-card-label {
    font-family: var(--font-body);
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--aqua-pale);
    margin-bottom: 4px;
  }
  .dark-card-value {
    font-family: var(--font-display);
    font-size: clamp(1.05rem, 5vw, 1.3rem);
    font-weight: 600;
    color: var(--white);
    line-height: 1.3;
  }
  .dark-card-detail {
    font-family: var(--font-body);
    font-size: 12px;
    color: rgba(255,255,255,0.65);
    margin-top: 4px;
    line-height: 1.5;
  }

  /* ─── MAP BUTTON ─── */
  .map-btn-wrapper { padding: 8px 0 4px; text-align: center; }
  .map-btn {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: linear-gradient(135deg, var(--gold) 0%, var(--gold-light) 100%);
    color: var(--text-dark);
    text-decoration: none;
    font-family: var(--font-body);
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.06em;
    padding: 16px 28px;
    border-radius: 50px;
    box-shadow: 0 4px 20px rgba(200,168,75,0.35);
    transition: transform 0.2s, box-shadow 0.2s;
    min-height: 52px;
    -webkit-tap-highlight-color: transparent;
    width: 100%;
    max-width: 340px;
    justify-content: center;
  }
  .map-btn:active { transform: scale(0.97); box-shadow: 0 2px 10px rgba(200,168,75,0.25); }
  .map-btn-icon { font-size: 18px; }
  .map-btn-text { line-height: 1.2; text-align: left; }
  .map-btn-sub {
    display: block;
    font-size: 10px;
    font-weight: 400;
    letter-spacing: 0.02em;
    opacity: 0.75;
    margin-top: 1px;
  }

  /* ─── WHATSAPP RSVP BUTTON ─── */
  .rsvp-section {
    background: linear-gradient(160deg, #e8f8ee 0%, #f0fdf4 50%, var(--aqua-foam) 100%);
    padding: 36px 28px 40px;
    text-align: center;
  }
  .rsvp-title {
    font-family: var(--font-display);
    font-size: clamp(1.6rem, 8vw, 2.2rem);
    font-weight: 600;
    color: var(--aqua-deep);
    margin-bottom: 6px;
  }
  .rsvp-subtitle {
    font-family: var(--font-body);
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #2e7d52;
    margin-bottom: 20px;
  }
  .rsvp-text {
    font-family: var(--font-body);
    font-size: 13px;
    color: #3a6650;
    line-height: 1.65;
    margin-bottom: 24px;
    max-width: 340px;
    margin-left: auto;
    margin-right: auto;
  }
  .rsvp-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    background: linear-gradient(135deg, #25D366 0%, #128C7E 100%);
    color: #ffffff;
    text-decoration: none;
    font-family: var(--font-body);
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0.04em;
    padding: 16px 28px;
    border-radius: 50px;
    box-shadow: 0 6px 24px rgba(37,211,102,0.35);
    transition: transform 0.2s, box-shadow 0.2s;
    min-height: 54px;
    -webkit-tap-highlight-color: transparent;
    width: 100%;
    max-width: 340px;
    margin: 0 auto;
  }
  .rsvp-btn:active { transform: scale(0.97); box-shadow: 0 3px 12px rgba(37,211,102,0.2); }
  .rsvp-btn-icon { font-size: 24px; flex-shrink: 0; }
  .rsvp-btn-text { text-align: left; }
  .rsvp-btn-sub {
    display: block;
    font-size: 11px;
    font-weight: 400;
    opacity: 0.85;
    margin-top: 2px;
  }
  .rsvp-note {
    font-family: var(--font-body);
    font-size: 11px;
    color: #6aab88;
    margin-top: 14px;
    font-style: italic;
  }

  /* ─── PARKING PILL ─── */
  .parking-pill {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(255,255,255,0.15);
    border: 1px solid rgba(255,255,255,0.25);
    border-radius: 50px;
    padding: 10px 18px;
    margin-top: 8px;
  }
  .parking-pill span {
    font-family: var(--font-body);
    font-size: 12px;
    color: rgba(255,255,255,0.9);
    font-weight: 500;
  }
  .parking-badge {
    background: var(--gold);
    color: var(--text-dark);
    font-family: var(--font-body);
    font-size: 10px;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 20px;
    letter-spacing: 0.05em;
  }

  /* ─── WAVE DIVIDER ─── */
  .wave-divider {
    display: block;
    width: 100%;
    overflow: hidden;
    line-height: 0;
  }

  /* ─── FOOTER ─── */
  .footer {
    background: var(--aqua-deep);
    padding: 36px 28px 52px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .footer::before {
    content: '';
    position: absolute;
    top: -80px; left: 50%;
    transform: translateX(-50%);
    width: 260px; height: 260px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(255,255,255,0.04) 0%, transparent 70%);
  }
  .footer-ornament {
    font-family: var(--font-display);
    font-size: 34px;
    color: var(--gold);
    letter-spacing: 10px;
    margin-bottom: 14px;
  }
  .footer-tagline {
    font-family: var(--font-display);
    font-size: clamp(1rem, 5vw, 1.35rem);
    font-style: italic;
    font-weight: 300;
    color: rgba(255,255,255,0.8);
    line-height: 1.6;
  }
  .footer-sub {
    font-family: var(--font-body);
    font-size: 10px;
    font-weight: 400;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: rgba(255,255,255,0.35);
    margin-top: 18px;
  }

  @media print {
    .map-btn, .rsvp-btn { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  }
</style>
</head>
<body>
<div class="page">

  <!-- ═══════════════════════════════════════════
       IMMAGINE 1 — Countdown (allegata)
  ═══════════════════════════════════════════ -->
  <div class="hero-img-wrap">
    <img src="data:image/jpeg;base64,"
         alt="Mancano 50 giorni al matrimonio"
         width="480"
         loading="eager">
    <div class="hero-img-overlay"></div>
  </div>

  <!-- ═══════════════════════════════════════════
       IMMAGINE 2 — Data e location (allegata)
  ═══════════════════════════════════════════ -->
  <div class="date-img-wrap">
    <div class="date-img-overlay-top"></div>
    <img src="data:image/jpeg;base64,"
         alt="Ci sposiamo! 26 Luglio 2026 – Anzio, Roma"
         width="480"
         loading="eager">
    <div class="date-img-overlay-bottom"></div>
  </div>

  <!-- ═══════════════════════════════════════════
       DETTAGLI CERIMONIA
  ═══════════════════════════════════════════ -->
  <div class="section section-alt">
    <div class="section-icon icon-aqua">🌊</div>
    <h2 class="section-title">La Cerimonia</h2>
    <p class="section-subtitle">Quando &amp; Dove</p>
    <div class="gold-line"></div>

    <div class="info-card">
      <span class="info-card-icon">📅</span>
      <div>
        <div class="info-card-label">Data</div>
        <div class="info-card-value">Domenica 26 Luglio 2026</div>
      </div>
    </div>

    <div class="info-card">
      <span class="info-card-icon">🕕</span>
      <div>
        <div class="info-card-label">Orario</div>
        <div class="info-card-value">Ore 18:00</div>
        <div class="info-card-detail">Cerimonia e ricevimento in successione</div>
      </div>
    </div>

    <div class="info-card">
      <span class="info-card-icon">📍</span>
      <div>
        <div class="info-card-label">Location</div>
        <div class="info-card-value">Sunset House Events</div>
        <div class="info-card-detail">Via Ardeatina 53, Anzio (RM)</div>
      </div>
    </div>

    <div class="map-btn-wrapper" style="margin-top:8px;">
      <a class="map-btn"
         href="https://www.google.com/maps/place/Sunset+Events%2FTramonto+Eventi,+Via+Ardeatina,+53,+00042+Anzio+RM/@41.4608709,12.6125167,17z/data=!4m9!1m2!2m1!1sSunset+House+event+anzio!3m5!1s0x1325bbf7582fc47b:0x36aaa425151778f5!8m2!3d41.4608709!4d12.6125167!16s%2Fg%2F11y9d1dh07"
         target="_blank"
         rel="noopener noreferrer">
        <span class="map-btn-icon">🗺️</span>
        <span class="map-btn-text">
          Apri la Mappa su Google Maps
          <span class="map-btn-sub">Sunset House Events · Via Ardeatina 53, Anzio</span>
        </span>
      </a>
    </div>
  </div>

  <!-- Wave -->
  <div class="wave-divider" style="background: var(--aqua-mist);">
    <svg viewBox="0 0 480 28" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg" style="display:block;width:100%;height:28px;">
      <path d="M0,0 C80,28 200,0 320,20 C400,35 450,5 480,15 L480,28 L0,28 Z" fill="white"/>
    </svg>
  </div>

  <!-- ═══════════════════════════════════════════
       INFO DRESS CODE & TERRAZZA
  ═══════════════════════════════════════════ -->
  <div class="section">
    <div class="section-icon icon-gold">✨</div>
    <h2 class="section-title">Un'Info Importante</h2>
    <p class="section-subtitle">Dress code &amp; Location</p>
    <div class="gold-line"></div>

    <div class="highlight-box">
